package release

import (
	"errors"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/stricttools/strictcli/go/strictcli"

	"github.com/stricttools/rlsbl/internal/git"
)

// CommitResult is what `rlsbl commit` committed.
type CommitResult struct {
	// Paths are the named files, repository-relative.
	Paths []string
}

// CommitFiles commits the named files of the repository holding the
// absolute directory dir through safegit, with the Autogenerated: true
// trailer, so changelog coverage exempts the commit. A file is named
// relative to dir or absolutely, and must lie inside the repository. A
// named file that did not change is left out of the commit; a commit none of
// whose files changed is refused.
func CommitFiles(e *strictcli.Effects, dir, message string, files []string) (CommitResult, error) {
	if strings.TrimSpace(message) == "" {
		return CommitResult{}, errors.New("--message must not be empty: it is the commit's message")
	}
	if len(files) == 0 {
		return CommitResult{}, errors.New("name the files to commit: rlsbl commit --message <message> <file> [<file> ...]")
	}
	here, err := filepath.EvalSymlinks(dir)
	if err != nil {
		return CommitResult{}, err
	}
	probe, err := git.Open(e, here)
	if err != nil {
		return CommitResult{}, err
	}
	root, err := probe.Toplevel()
	if err != nil {
		return CommitResult{}, err
	}
	repo, err := git.Open(e, root)
	if err != nil {
		return CommitResult{}, err
	}
	var paths []string
	for _, f := range files {
		rel, err := repositoryPath(root, here, f)
		if err != nil {
			return CommitResult{}, err
		}
		paths = append(paths, rel)
	}
	if _, err := repo.Commit(git.CommitRequest{Message: message, Paths: paths, Autogenerated: true, RequireChange: true}); err != nil {
		return CommitResult{}, err
	}
	return CommitResult{Paths: paths}, nil
}

// repositoryPath is file (relative to here, or absolute) as a path relative
// to the repository root. The directory part is resolved through symbolic
// links, so a file that no longer exists (a deletion being committed) is
// still placed; a file outside the repository is refused.
func repositoryPath(root, here, file string) (string, error) {
	if strings.TrimSpace(file) == "" {
		return "", errors.New("a file to commit is named by an empty argument")
	}
	abs := file
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(here, file)
	} else {
		parent, err := filepath.EvalSymlinks(filepath.Dir(abs))
		if err == nil {
			abs = filepath.Join(parent, filepath.Base(abs))
		}
	}
	rel, err := filepath.Rel(root, filepath.Clean(abs))
	if err != nil {
		return "", err
	}
	rel = filepath.ToSlash(rel)
	if rel == "." || rel == ".." || strings.HasPrefix(rel, "../") {
		return "", fmt.Errorf("%s is not a file inside the repository %s", file, root)
	}
	return rel, nil
}
